import numpy as np, pandas as pd, sys
from scipy.optimize import minimize
from itertools import combinations

BANDS = ['VV','VH','VV-VH']

def load():
    df = pd.read_csv('data.csv')
    piv = df.pivot(index='band', columns='period_id', values='mean_value').loc[BANDS]
    piv = piv[sorted(piv.columns)]
    return piv.values.astype(float)

def gauss_smooth(x, h):
    n = len(x); t = np.arange(n, dtype=float); out = np.zeros(n)
    for i in range(n):
        w = np.exp(-0.5*((t-t[i])/h)**2)
        X = np.column_stack([np.ones(n), t-t[i]])
        XtW = X.T*w
        beta = np.linalg.solve(XtW@X + 1e-12*np.eye(2), XtW@x)
        out[i] = beta[0]
    return out

def prepare_band(x, h):
    n = len(x); t = np.arange(n, dtype=float)
    X = np.column_stack([np.ones(n), t])
    beta = np.linalg.lstsq(X, x, rcond=None)[0]
    r = x - X@beta
    S = np.column_stack([np.sin(2*np.pi*t/12), np.cos(2*np.pi*t/12)])
    g = np.linalg.lstsq(S, r, rcond=None)[0]
    deseason = x - S@g
    sm = gauss_smooth(deseason, h)
    mu, sd = sm.mean(), sm.std()
    if sd < 1e-9: sd = 1.0
    return (sm-mu)/sd, g, mu, sd

def prepare(Y, h):
    Z = np.zeros_like(Y); coefs=[]; mus=[]; sds=[]
    for b in range(Y.shape[0]):
        z,g,mu,sd = prepare_band(Y[b], h)
        Z[b]=z; coefs.append(g); mus.append(mu); sds.append(sd)
    return Z, coefs, np.array(mus), np.array(sds)

def seasonal_at(coefs, t):
    return np.array([g[0]*np.sin(2*np.pi*t/12)+g[1]*np.cos(2*np.pi*t/12) for g in coefs])

def make_blocks(Z, m, n=1):
    T = Z.shape[1]; blocks=[]
    for i in range(T-m-n+1):
        blocks.append((Z[:, i:i+m], Z[:, i+m:i+m+n]))
    return blocks

def fit_weights(blocks, target, subset):
    D = np.column_stack([blocks[i][0].flatten() for i in subset])
    y = target.flatten(); k = len(subset)
    def obj(w):
        r = D@w - y
        return float(r@r)
    if k == 1:
        return np.array([1.0]), obj(np.array([1.0]))
    cons = [{'type':'eq','fun': lambda w: w.sum()-1.0}]
    bnds = [(0.0,1.0)]*k
    res = minimize(obj, np.ones(k)/k, bounds=bnds, constraints=cons,
                   method='SLSQP', options={'maxiter':800,'ftol':1e-14})
    w = res.x if res.success else np.ones(k)/k
    w = np.clip(w,0,None)
    if w.sum() > 0: w = w/w.sum()
    return w, obj(w)

def select_exhaustive(blocks, target):
    k = len(blocks); best=None
    for r in range(1, k+1):
        for sub in combinations(range(k), r):
            w,e = fit_weights(blocks, target, list(sub))
            if best is None or e < best[1]-1e-15:
                best = (list(sub), e)
    return best

def select_stepwise(blocks, target, tol):
    k = len(blocks); best=None
    for i in range(k):
        w,e = fit_weights(blocks, target, [i])
        if best is None or e < best[1]:
            best = ([i], e)
    cur, cur_err = best
    while len(cur) < k:
        cand=None
        for j in range(k):
            if j in cur: continue
            sub = cur+[j]
            w,e = fit_weights(blocks, target, sub)
            if cand is None or e < cand[1]:
                cand = (sub, e)
        if cand is not None and (cur_err - cand[1]) > tol:
            cur, cur_err = cand
        else:
            break
    return cur, cur_err

def predict_next(Yhist, cfg):
    m = cfg['m']; h = cfg['h']; sel = cfg['sel']; tol = cfg['tol']
    T = Yhist.shape[1]
    if cfg['prepared']:
        Z, coefs, mus, sds = prepare(Yhist, h)
    else:
        Z = Yhist
    blocks = make_blocks(Z, m, 1)
    target = Z[:, T-m:]
    if sel == 'exhaustive':
        subset, err = select_exhaustive(blocks, target)
    else:
        subset, err = select_stepwise(blocks, target, tol)
    w, err = fit_weights(blocks, target, subset)
    pred_z = sum(w[j]*blocks[subset[j]][1][:,0] for j in range(len(subset)))
    if cfg['prepared']:
        pred = pred_z*sds + mus + seasonal_at(coefs, T)
    else:
        pred = pred_z
    return pred, err, subset

def backtest(Y, cfg, ks=(1,2,3)):
    errs=[]
    for k in ks:
        if Y.shape[1]-k < cfg['m']+1: continue
        hist = Y[:, :Y.shape[1]-k]; actual = Y[:, Y.shape[1]-k]
        pred,_,_ = predict_next(hist, cfg)
        errs.append(float(((pred-actual)**2).mean()))
    return np.mean(errs) if errs else np.inf

def main():
    Y = load()
    configs=[]
    for m in (2,3,4):
        for sel in ('exhaustive','stepwise'):
            configs.append(dict(prepared=False, m=m, h=1.0, sel=sel, tol=1e-3))
    for m in (2,3,4):
        for h in (1.0,2.0):
            for sel in ('exhaustive','stepwise'):
                configs.append(dict(prepared=True, m=m, h=h, sel=sel, tol=1e-3))
    scored=[]
    for cfg in configs:
        e = backtest(Y, cfg)
        scored.append((e, cfg))
    scored.sort(key=lambda x: x[0])
    for e,cfg in scored[:6]:
        print(f"BT {e:.5f} {cfg}", file=sys.stderr)
    best_e, best_cfg = scored[0]
    print(f"CHOSEN {best_cfg} bt={best_e:.5f}", file=sys.stderr)
    pred, err, subset = predict_next(Y, best_cfg)
    print(f"subset={subset} match_err={err:.5f}", file=sys.stderr)
    for b, v in zip(BANDS, pred):
        print(f"{b} {v:.6f}")

main()
