    if nblocks < 1: return None
    M = np.zeros((m*nb, nblocks)); F = np.zeros((n*nb, nblocks))
    for b in range(nblocks):
        M[:,b] = data[b:b+m].reshape(-1)
        F[:,b] = data[b+m:b+m+n].reshape(-1)
    W = data[T-m:T].reshape(-1)
    e, idx, w = fit_weights(M, W, selection)
    pred_prep = F[:nb, idx] @ w
    if prepared:
        tt = T
        seas_t = np.sin(2*np.pi*tt/12)*sc[0] + np.cos(2*np.pi*tt/12)*sc[1]
        pred = pred_prep*sd + mu + seas_t
    else:
        pred = pred_prep
    return pred

def main():
    mat, periods = load()
    T = mat.shape[0]
    bstd = mat.std(0); bstd[bstd==0]=1
    settings=[]
    for m in [2,3,4]:
        for prepared in [False,True]:
            for h in ([1.0,1.5,2.0] if prepared else [1.0]):
                for sel in ['exhaustive','stepwise']:
                    settings.append((m,prepared,h,sel))
    results=[]
    for (m,prepared,h,sel) in settings:
        errs=[]
        for e in range(m+1, T):
            pred = predict_next(mat[:e], m, 1, prepared, h, sel)
            if pred is None: continue
            errs.append(np.mean(((pred-mat[e])/bstd)**2))
        if errs:
            results.append((np.mean(errs), m, prepared, h, sel, len(errs)))
    results.sort()
    print("Validation (lower=better):", file=sys.stderr)
    for r in results[:12]:
        print(f"  mse={r[0]:.5f} m={r[1]} prep={r[2]} h={r[3]} sel={r[4]} n={r[5]}", file=sys.stderr)
    best = results[0]
    m,prepared,h,sel = best[1],best[2],best[3],best[4]
    print(f"Chosen: m={m} prep={prepared} h={h} sel={sel}", file=sys.stderr)
    pred = predict_next(mat, m, 1, prepared, h, sel)
    for b,v in zip(BANDS, pred):
        print(f"{b} {v:.6f}")

if __name__=='__main__':
    main()
